import * as T from 'three';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
import {inside,distance,nearestSegment} from './world-geometry.js';

export function createGroundDetails(scene,data,paths,materials,blocked,stoneMaterial){
 const greens=data.features.filter(f=>f.properties.layer==='vegetation'&&f.geometry.type==='Polygon').map(f=>{const ring=f.geometry.coordinates[0],x=ring.map(p=>p[0]),z=ring.map(p=>p[1]);return{rings:f.geometry.coordinates,minX:Math.min(...x),maxX:Math.max(...x),minZ:Math.min(...z),maxZ:Math.max(...z)};});
 const segments=[];for(const path of paths.filter(p=>!p.private))for(let i=1;i<path.points.length;i++){const a=path.points[i-1],b=path.points[i];segments.push({a,b,path,minX:Math.min(a[0],b[0])-path.width,maxX:Math.max(a[0],b[0])+path.width,minZ:Math.min(a[1],b[1])-path.width,maxZ:Math.max(a[1],b[1])+path.width});}
 const curbGeometry=[],grateGeometry=[],curbMaterial=(stoneMaterial||materials.wall).clone();curbMaterial.color.set('#bcbcaf');curbMaterial.roughness=1;curbMaterial.normalScale.set(.7,.7);
 const matrix=new T.Matrix4(),dummy=new T.Object3D();
 for(const seg of segments){if(seg.path.bridge)continue;const len=distance(seg.a,seg.b);if(len<1)continue;const dx=(seg.b[0]-seg.a[0])/len,dz=(seg.b[1]-seg.a[1])/len,nx=-dz,nz=dx,n=Math.ceil(len/1.2),step=len/n,near=segments.filter(s=>s!==seg&&s.maxX>seg.minX-2&&s.minX<seg.maxX+2&&s.maxZ>seg.minZ-2&&s.minZ<seg.maxZ+2);
  for(let i=0;i<n;i++)for(const side of[-1,1]){const d=(i+.5)*step,x=seg.a[0]+dx*d+nx*side*(seg.path.width/2+.04),z=seg.a[1]+dz*d+nz*side*(seg.path.width/2+.04),p=[x,z];if(blocked(p)||near.some(s=>nearestSegment(p,s.a,s.b).distance<s.path.width/2+.08))continue;
   const green=greens.some(g=>x>=g.minX-.3&&x<=g.maxX+.3&&z>=g.minZ-.3&&z<=g.maxZ+.3);if(!green)continue;
   const geo=new T.BoxGeometry(step-.022,.13,.22,1,1,1);dummy.position.set(x,.106,z);dummy.rotation.set(0,Math.atan2(-dz,dx),0);dummy.scale.setScalar(1);dummy.updateMatrix();geo.applyMatrix4(dummy.matrix);const pos=geo.attributes.position,uv=geo.attributes.uv;for(let k=0;k<pos.count;k++)uv.setXY(k,(pos.getX(k)+pos.getZ(k))/1.4,pos.getY(k)/1.4);curbGeometry.push(geo);
   if(i%31===15){for(let k=0;k<9;k++){const g=new T.BoxGeometry(.024,.018,.32);dummy.position.set(x-nx*side*.28+dx*(k-4)*.05,.098,z-nz*side*.28+dz*(k-4)*.05);dummy.updateMatrix();g.applyMatrix4(dummy.matrix);grateGeometry.push(g);}}
  }
 }
 function merged(list,mat){if(!list.length)return;const mesh=new T.Mesh(mergeGeometries(list,false),mat);mesh.castShadow=false;mesh.receiveShadow=true;scene.add(mesh);list.forEach(g=>g.dispose());return mesh;}
 merged(curbGeometry,curbMaterial);merged(grateGeometry,new T.MeshStandardMaterial({color:'#3a403b',roughness:.82,metalness:.45}));
 const vertices=[],colors=[],normals=[],seed=n=>{const s=Math.sin(n*127.1+311.7)*43758.5453;return s-Math.floor(s);};
 for(let blade=0;blade<9;blade++){const angle=seed(blade+1)*Math.PI*2,h=.035+seed(blade+19)*.065,w=.0045+seed(blade+40)*.003,x=(seed(blade+61)-.5)*.08,z=(seed(blade+81)-.5)*.08,dx=Math.cos(angle),dz=Math.sin(angle),bend=.022*seed(blade+101);const p=[[x-dx*w,0,z-dz*w],[x+dx*w,0,z+dz*w],[x-dx*w*.45+dz*bend,h*.6,z-dz*w*.45-dx*bend],[x+dx*w*.45+dz*bend,h*.6,z+dz*w*.45-dx*bend],[x+dz*bend*1.9,h,z-dx*bend*1.9]];for(const i of[0,1,2,2,1,3,2,3,4]){vertices.push(...p[i]);const t=p[i][1]/h;colors.push(.12+t*.11,.2+t*.18,.055+t*.06);}}
 const bladeGeo=new T.BufferGeometry();bladeGeo.setAttribute('position',new T.Float32BufferAttribute(vertices,3));bladeGeo.setAttribute('color',new T.Float32BufferAttribute(colors,3));bladeGeo.computeVertexNormals();const grassMat=new T.MeshStandardMaterial({vertexColors:true,side:T.DoubleSide,roughness:1,metalness:0,envMapIntensity:.25}),field=new T.InstancedMesh(bladeGeo,grassMat,24000);field.frustumCulled=false;field.count=0;field.receiveShadow=true;scene.add(field);let last=-1,high=true,lastX=Infinity,lastZ=Infinity,lastGround=false;
 return{setQuality:v=>{high=v;last=-1;},update(t,camera){if(t-last<.4)return;if(last>=0&&lastGround===(camera.position.y<=8)&&Math.hypot(camera.position.x-lastX,camera.position.z-lastZ)<1.4)return;last=t;lastGround=camera.position.y<=8;lastX=camera.position.x;lastZ=camera.position.z;if(camera.position.y>8){field.count=0;return;}const radius=high?11:7,spacing=high?.13:.19,cx=Math.round(lastX/spacing)*spacing,cz=Math.round(lastZ/spacing)*spacing,localGreens=greens.filter(g=>g.maxX>cx-radius&&g.minX<cx+radius&&g.maxZ>cz-radius&&g.minZ<cz+radius),localPaths=segments.filter(s=>s.maxX>cx-radius&&s.minX<cx+radius&&s.maxZ>cz-radius&&s.minZ<cz+radius);let count=0;
  for(let x=cx-radius;x<cx+radius;x+=spacing)for(let z=cz-radius;z<cz+radius;z+=spacing){const d=Math.hypot(x-cx,z-cz);if(d>radius||count>=24000)continue;const p=[x+(seed(x*4+z)-.5)*spacing,z+(seed(z*5+x)-.5)*spacing];if(!localGreens.some(g=>p[0]>g.minX&&p[0]<g.maxX&&p[1]>g.minZ&&p[1]<g.maxZ&&inside(p,g.rings[0])&&!g.rings.slice(1).some(r=>inside(p,r)))||localPaths.some(s=>nearestSegment(p,s.a,s.b).distance<s.path.width/2+.08)||blocked(p))continue;const fade=1-T.MathUtils.smoothstep(d,radius-3,radius);dummy.position.set(p[0],.036,p[1]);dummy.rotation.set(0,seed(x+z)*6.28,0);dummy.scale.setScalar(fade*(.8+seed(x-z)*.4));dummy.updateMatrix();field.setMatrixAt(count++,dummy.matrix);}
  field.count=count;field.instanceMatrix.needsUpdate=true;
 }};
}
